CREATE DATABASE IF NOT EXISTS atti_ticketing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE atti_ticketing;
CREATE TABLE roles (id INT AUTO_INCREMENT PRIMARY KEY, nama_role VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE units (id INT AUTO_INCREMENT PRIMARY KEY, nama_unit VARCHAR(100) NOT NULL);
CREATE TABLE jenis_keluhan (id INT AUTO_INCREMENT PRIMARY KEY, nama_jenis VARCHAR(100) NOT NULL);
CREATE TABLE sparepart (id INT AUTO_INCREMENT PRIMARY KEY, nama_sparepart VARCHAR(120) NOT NULL, satuan VARCHAR(30), stok INT NOT NULL DEFAULT 0);
CREATE TABLE status_tiket (id INT AUTO_INCREMENT PRIMARY KEY, nama_status VARCHAR(50) NOT NULL, color_code VARCHAR(10) NOT NULL, urutan TINYINT NOT NULL);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(120) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, no_hp VARCHAR(25), password VARCHAR(255) NOT NULL, role_id INT NOT NULL, unit_id INT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(unit_id) REFERENCES units(id));
CREATE TABLE tickets (id INT AUTO_INCREMENT PRIMARY KEY, no_tiket VARCHAR(30) NOT NULL UNIQUE, user_id INT NULL, nama_pelapor VARCHAR(120) NOT NULL, unit_id INT NOT NULL, tanggal_lapor DATETIME NOT NULL, jenis_keluhan_id INT NOT NULL, jenis_lainnya VARCHAR(120), deskripsi_aduan TEXT NOT NULL, kelengkapan_barang TEXT, keluhan_pengguna TEXT, ttd_pelapor VARCHAR(255), status_id INT NOT NULL, source ENUM('self','teknisi') NOT NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(unit_id) REFERENCES units(id), FOREIGN KEY(jenis_keluhan_id) REFERENCES jenis_keluhan(id), FOREIGN KEY(status_id) REFERENCES status_tiket(id));
CREATE TABLE ticket_signatures (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, tipe ENUM('lapor','konfirmasi_selesai') NOT NULL, file_path VARCHAR(255) NOT NULL, waktu DATETIME NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE);
CREATE TABLE ticket_handling (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL UNIQUE, teknisi_id INT NOT NULL, kode_barcode_terima VARCHAR(50), waktu_terima DATETIME, waktu_mulai DATETIME, analisa_keluhan TEXT, penyelesaian TEXT, waktu_selesai DATETIME, kode_selesai VARCHAR(50), FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(teknisi_id) REFERENCES users(id));
CREATE TABLE ticket_sparepart (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, sparepart_id INT NULL, nama_sparepart_manual VARCHAR(120), jumlah INT NOT NULL DEFAULT 1, keterangan TEXT, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(sparepart_id) REFERENCES sparepart(id));
CREATE TABLE ticket_approval (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, atasan_id INT NOT NULL, kode_barcode_approve VARCHAR(50), waktu_approve DATETIME NOT NULL, status ENUM('approve','reject') NOT NULL, catatan TEXT, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(atasan_id) REFERENCES users(id));
CREATE TABLE ticket_logs (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, field_yang_diubah VARCHAR(80) NOT NULL, nilai_lama TEXT, nilai_baru TEXT, diubah_oleh INT NULL, waktu_perubahan DATETIME NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY(diubah_oleh) REFERENCES users(id));
CREATE TABLE notification_logs (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, tipe ENUM('email','wa') NOT NULL, tujuan VARCHAR(160) NOT NULL, status_kirim VARCHAR(50) NOT NULL, waktu_kirim DATETIME NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id) ON DELETE CASCADE);
